use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut total_time = 0;
    let mut server = 0;

    for (arrival, duration) in arr {
        let arrival = arrival.as_i64().unwrap();
        let duration = duration.as_i64().unwrap();

        if server == 0 {
            total_time += arrival;
        } else {
            total_time += (arrival - server) as i64;
        }

        server = (server + 1) % arr.len();
    }

    Value::from(total_time)
}
